//! Per-domain eBPF map code: mirror types (`<domain>/types.rs`), runtime map
//! setting/syncing logic (`<domain>/setting.rs`) and startup map
//! creation/pinning (`<domain>/init.rs`).
//!
//! Mirror structs are hand-written Rust definitions of the corresponding C
//! structs (generated by libbpf-cargo into `src/bpf_rs/*.skel.rs`). Layouts are
//! pinned by layout consistency tests at the bottom of each `types.rs`: if a C
//! header change drifts a size or field offset, `cargo test` fails loudly
//! instead of silently corrupting maps at runtime.
//!
//! Encoding/decoding goes through zerocopy derives. C unions are modeled as
//! raw byte arrays (e.g. `[u8; 16]`) because the union exactly overlays those
//! bytes, making the representations byte-for-byte equivalent. Implicit
//! padding is rejected by `IntoBytes`, so it must be spelled out explicitly as
//! `_pad` / `_pad_tail` fields.
//!
//! Shared maps are created and pinned directly from Rust (`bpf_map_create`,
//! no C skeleton) by the per-domain `<domain>/init.rs` modules, orchestrated
//! from [`init_path`]. Every BPF program still declares its own copy of the
//! shared map (C headers) and reuses the pinned map on load, so the creation
//! parameters must stay in lockstep with the C definitions — the per-domain
//! `init.rs` tests compare them against the real skeleton map defs.
//!
//! Domain-agnostic helpers (raw-byte map diffing, pinned-map reuse, map
//! creation specs) live in this root module.

use std::{
    collections::HashMap,
    net::Ipv6Addr,
    os::fd::{AsFd, AsRawFd},
    path::Path,
};

use libbpf_rs::{AsRawLibbpf, MapCore, MapFlags, MapHandle, MapType, OpenMapMut};

use crate::bpf_error::LdEbpfResult;
use crate::LandscapeMapPath;

/// Typed accessors for the `u_inet_addr` / `u_inet6_addr` unions modeled as
/// `[u8; 16]`.
///
/// IPv4 reads/writes the `ip` variant (first 4 bytes, network order); IPv6
/// maps to the `bits` variant (all 16 bytes, network order).
pub(crate) trait Inet6Bytes: AsRef<[u8]> + AsMut<[u8]> {
    fn set_ipv4_be(&mut self, addr: u32) {
        self.as_mut()[..4].copy_from_slice(&addr.to_be_bytes());
    }

    #[cfg_attr(not(test), allow(dead_code))]
    fn ipv4(&self) -> u32 {
        u32::from_be_bytes(self.as_ref()[..4].try_into().unwrap())
    }

    fn set_ipv6(&mut self, addr: Ipv6Addr) {
        self.as_mut()[..16].copy_from_slice(&addr.octets());
    }
}

impl Inet6Bytes for [u8; 16] {}

/// Mirror and skel type sizes must match.
#[cfg(test)]
macro_rules! assert_size {
    ($mirror:ty, $skel:ty) => {
        assert_eq!(
            std::mem::size_of::<$mirror>(),
            std::mem::size_of::<$skel>(),
            concat!("size mismatch: ", stringify!($mirror), " vs ", stringify!($skel)),
        );
    };
}

/// Mirror and skel field offsets must match (nested paths supported).
#[cfg(test)]
macro_rules! assert_field {
    ($mirror:ty, $skel:ty, $($field:tt).+) => {
        assert_eq!(
            std::mem::offset_of!($mirror, $($field).+),
            std::mem::offset_of!($skel, $($field).+),
            concat!(
                "offset mismatch: ",
                stringify!($mirror),
                ".",
                stringify!($($field).+),
            ),
        );
    };
}

/// When field names differ (union modeling / nested flattening), specify the
/// mirror and skel field paths separately.
#[cfg(test)]
macro_rules! assert_field_as {
    ($mirror:ty, $($mfield:tt).+, $skel:ty, $($sfield:tt).+) => {
        assert_eq!(
            std::mem::offset_of!($mirror, $($mfield).+),
            std::mem::offset_of!($skel, $($sfield).+),
            concat!(
                "offset mismatch: ",
                stringify!($mirror),
                ".",
                stringify!($($mfield).+),
                " vs ",
                stringify!($skel),
                ".",
                stringify!($($sfield).+),
            ),
        );
    };
}

