    #[test]
    fn map_in_map_outer_is_never_silently_reused() {
        let Some(_) = run_or_skip("init-map-in-map-no-reuse", |root| {
            let inner = InnerMapSpec {
                map_type: MapType::LruHash,
                name: "test_inner",
                key_size: 4,
                value_size: 8,
                max_entries: 16,
                map_flags: 0,
            };
            let spec = MapCreateSpec {
                map_type: MapType::HashOfMaps,
                name: "test_outer",
                key_size: 4,
                value_size: 4,
                max_entries: 8,
                map_flags: 0,
                inner: Some(inner),
            };
            let pin = root.join("test_outer");

            // Create once and bind a real inner map to slot 7.
            let outer = ensure_pinned_map(&spec, &pin).expect("create outer");
            let inner_map =
                MapHandle::create(MapType::LruHash, None::<&str>, 4, 8, 16, &probe_opts())
                    .expect("create inner");
            let fd = inner_map.as_fd().as_raw_fd().to_ne_bytes();
            outer.update(&7u32.to_ne_bytes(), &fd, MapFlags::ANY).expect("attach inner");
            drop((outer, inner_map));

            // A map-in-map outer is never trusted for reuse, so the identical
            // spec must still rebuild the outer and drop the bound inner map.
            let outer2 = ensure_pinned_map(&spec, &pin).expect("recreate outer");
            assert!(
                outer2.lookup(&7u32.to_ne_bytes(), MapFlags::ANY).expect("lookup").is_none(),
                "map-in-map outer must be recreated, dropping the bound inner map"
            );
        }) else {
            return;
        };
    }

    #[test]
    fn ensure_pinned_map_creates_map_in_map_outer() {
        let Some(_) = run_or_skip("init-map-in-map", |root| {
            let inner = InnerMapSpec {
                map_type: MapType::LruHash,
                name: "test_inner",
                key_size: 4,
                value_size: 8,
                max_entries: 16,
                map_flags: 0,
            };
            let spec = MapCreateSpec {
                map_type: MapType::HashOfMaps,
                name: "test_outer",
                key_size: 4,
                value_size: 4,
                max_entries: 8,
                map_flags: 0,
                inner: Some(inner),
            };

            let pin = root.join("test_outer");
            let outer = ensure_pinned_map(&spec, &pin).expect("create map-in-map");

            // The kernel must accept an inner LRU_HASH of the template's layout.
            let probe = libbpf_sys::bpf_map_create_opts {
                sz: std::mem::size_of::<libbpf_sys::bpf_map_create_opts>() as libbpf_sys::size_t,
                ..Default::default()
            };
            let inner_map = MapHandle::create(
                MapType::LruHash,
                None::<&str>,
                inner.key_size,
                inner.value_size,
                inner.max_entries,
                &probe,
            )
            .expect("create inner map");
            let fd = inner_map.as_fd().as_raw_fd().to_ne_bytes();
            outer.update(&7u32.to_ne_bytes(), &fd, MapFlags::ANY).expect("attach inner map");

            let info = libbpf_rs::MapInfo::new(outer.as_fd()).expect("outer info");
            assert_eq!(info.map_type(), MapType::HashOfMaps, "outer must be hash-of-maps");
        }) else {
            return;
        };
    }

